// Conceptual avoidance check performed before every grant
if (request <= available) {
    pretend_grant(request);          // tentatively update the state as if granted
    if (resulting_state_is_safe()) {
        actually_grant(request);     // safe, so commit the grant for real
    } else {
        undo_grant(request);         // not safe, roll the tentative grant back
        process_must_wait();         // wait even though the resource was free
    }
} else {
    process_must_wait();             // not enough of the resource exists at all
}

